enum LoanKind {
    REGULAR(2), SHORT(5);
    private final int dailyRate;
    LoanKind(int dailyRate) { this.dailyRate = dailyRate; }
    int fee(int days) { return dailyRate * days; }
}

class Main {
    public static void main(String[] args) throws Exception {
        for (LoanKind kind : LoanKind.values()) {
            System.out.println(kind.name() + " " + kind.fee(3));
        }
    }
}

enum DayType { LECTURE, LAB }

class Main {
    public static void main(String[] args) throws Exception {
        DayType type = DayType.LAB;
        int hours = switch (type) {
            case LECTURE -> 1;
            case LAB -> 3;
        };
        System.out.println(hours);
    }
}

record Mark(int roll, int score) {
    Mark {
        if (roll <= 0 || score < 0 || score > 100) {
            throw new IllegalArgumentException("Invalid mark");
        }
    }
}

class Main {
    public static void main(String[] args) throws Exception {
        Mark first = new Mark(7, 80);
        Mark second = new Mark(7, 80);
        System.out.println(first.roll() + " " + first.score());
        System.out.println(first.equals(second));
    }
}
